import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type FunnelAnalysisProps = Record<string, any>;

const FunnelAnalysis: React.FC<FunnelAnalysisProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  headerColor = "#143d2e",
  cardBackgroundColors = ["#fdf5f5", "#ebdff0", "#e0ccf5", "#d0b0f5"],
  titles = [
    "Market Evaluation",
    "Sales Analysis",
    "Content Utilization",
    "Training and Coaching",
  ],
  descriptions = [
    "Analyzing the market, evaluating the brand's position, and assessing competitors",
    "Evaluating the effectiveness of sales strategies and campaigns",
    "Ensuring the effectivity and impact of sales materials used in the sale process",
    "Maintaining the relevance of team training manuals and learning resources",
  ],
  textColor = "#1f1f1f",
  headerTextColor = "#ffffff",
}) => {
  useFontLoader(["Playfair Display", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Combine props into a unified data structure
  const data = useMemo(() => {
    return titles.map((title, i) => ({
      title,
      description: descriptions[i] || "",
      color: cardBackgroundColors[i % cardBackgroundColors.length],
    }));
  }, [titles, descriptions, cardBackgroundColors]);

  // Funnel Geometry Calculation
  const topWidth = 100; // viewBox units
  const bottomWidth = 30; // viewBox units
  const totalHeight = 100; // viewBox units
  
  // Equal height for all segments based on the number of items
  const segmentHeightFixed = data.length > 0 ? totalHeight / data.length : 0;

  // Calculate the path for each segment based on proportional value
  const getTrapezoidPath = (
    startY: number,
    segmentHeight: number
  ) => {
    const endY = startY + segmentHeight;

    // Linear interpolation for width at Y
    const getWidthAtY = (y: number) => {
      const progress = y / totalHeight;
      return topWidth - (topWidth - bottomWidth) * progress;
    };

    const wTop = getWidthAtY(startY);
    const wBottom = getWidthAtY(endY);

    const xTopLeft = (100 - wTop) / 2;
    const xTopRight = 100 - xTopLeft;
    const xBottomLeft = (100 - wBottom) / 2;
    const xBottomRight = 100 - xBottomLeft;

    return `M ${xTopLeft} ${startY} L ${xTopRight} ${startY} L ${xBottomRight} ${endY} L ${xBottomLeft} ${endY} Z`;
  };

  // Pre-calculate segments for SVG to maintain state across loop
  let currentYAccumulator = 0;
  const segments = data.map((item) => {
    const startY = currentYAccumulator;
    currentYAccumulator += segmentHeightFixed;
    return {
      ...item,
      startY,
      segmentHeight: segmentHeightFixed,
    };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          width: "100%",
          height: "100%",
          padding: `${height * 0.1}px ${width * 0.1}px`,
          gap: width * 0.05,
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Left Column: Cards */}
        <div
          style={{
            flex: 1,
            display: "flex",
            flexDirection: "column",
            height: "100%",
            gap: height * 0.02, // Add consistent gap between flexible cards
          }}
        >
          {data.map((item, index) => {
            const delay = index * 12; // Slightly faster stagger
            
            const slideIn = spring({
              frame: frame - delay,
              fps,
              config: { damping: 15, stiffness: 100, mass: 0.8 },
            });

            const opacity = interpolate(
              frame - delay,
              [0, 10],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            const translationX = interpolate(slideIn, [0, 1], [-80, 0]);
            const scaleCard = interpolate(slideIn, [0, 1], [0.9, 1]);

            return (
              <div
                key={index}
                style={{
                  flex: 1,
                  opacity,
                  transform: `translateX(${translationX}px) scale(${scaleCard})`,
                  display: "flex",
                  flexDirection: "column",
                  borderRadius: "8px",
                  overflow: "hidden",
                  boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)",
                  minHeight: 0,
                  borderLeft: `6px solid ${headerColor}`,
                }}
              >
                {/* Header */}
                <div
                  style={{
                    backgroundColor: "rgba(255,255,255,0.8)", // Subtler header
                    padding: "1.2vh 1.5vw",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "flex-start",
                    flex: "0 0 auto",
                    borderBottom: "1px solid rgba(0,0,0,0.05)",
                  }}
                >
                  <h3
                    style={{
                      fontFamily: "Playfair Display",
                      color: headerColor,
                      margin: 0,
                      fontSize: width * 0.015,
                      fontWeight: 700,
                      textAlign: "left",
                      letterSpacing: "0.02em",
                    }}
                  >
                    {item.title}
                  </h3>
                </div>
                {/* Body */}
                <div
                  style={{
                    backgroundColor: item.color,
                    flex: 1,
                    padding: "1vh 1.5vw",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "flex-start",
                    overflow: "hidden",
                  }}
                >
                  <p
                    style={{
                      fontFamily: "Inter",
                      color: textColor,
                      margin: 0,
                      fontSize: width * 0.011,
                      lineHeight: 1.5,
                      textAlign: "left",
                      display: "-webkit-box",
                      WebkitLineClamp: 3,
                      WebkitBoxOrient: "vertical",
                      overflow: "hidden",
                      opacity: 0.85,
                    }}
                  >
                    {item.description}
                  </p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Right Column: Creative Funnel */}
        <div
          style={{
            flex: 1,
            height: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            position: "relative",
          }}
        >
          <svg
            viewBox="0 0 100 100"
            style={{
              width: "85%",
              height: "100%",
              overflow: "visible",
              filter: "drop-shadow(0px 15px 15px rgba(0,0,0,0.15))",
            }}
            preserveAspectRatio="xMidYMid meet"
          >
            {segments.map((segment, i) => {
              const delay = i * 12;
              
              // More dynamic spring config
              const springVal = spring({
                frame: frame - delay,
                fps,
                config: { damping: 14, stiffness: 80, mass: 0.7 },
              });

              const opacity = interpolate(
                frame - delay,
                [0, 10],
                [0, 1],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              // Creative Entrance: Alternating sides fly-in + Rotation
              const direction = i % 2 === 0 ? -1 : 1;
              const startX = direction * 40; // Start off-center
              const startRotate = direction * -20; // Slight tilt

              const translateX = interpolate(springVal, [0, 1], [startX, 0]);
              const rotate = interpolate(springVal, [0, 1], [startRotate, 0]);
              const scale = interpolate(springVal, [0, 1], [0.6, 1]); // Grow from small

              return (
                <path
                  key={i}
                  d={getTrapezoidPath(segment.startY, segment.segmentHeight)}
                  fill={segment.color}
                  stroke="white"
                  strokeWidth="0.5"
                  style={{
                    opacity,
                    transformBox: "fill-box",
                    transformOrigin: "center center",
                    transform: `
                      translate(${translateX}px, 0px) 
                      rotate(${rotate}deg) 
                      scale(${scale})
                    `,
                  }}
                />
              );
            })}
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FunnelAnalysis;